 grammar=[
  dict(level="B1", title="Να σου πω: discourse openers",
       el="Μικρές φράσεις με «να» που ανοίγουν μια κουβέντα.",
       en="Spoken Greek opens a remark with short **να**-phrases: **να σου πω** (let me tell you, listen), **να σε ρωτήσω κάτι;** (can I ask you something?), **να ξέρεις** (you should know), **να σου πω την αλήθεια** (to tell you the truth). With **άκου** (listen) and **κοίτα** (look) they soften a complaint before it comes.",
       examples=[("Άκου, να σου πω, χθες ακουγόταν μουσική.", "Listen, I must tell you, there was music last night."), ("Να σε ρωτήσω κάτι;", "Can I ask you something?"), ("Να ξέρεις, το ασανσέρ χάλασε πάλι.", "Just so you know, the lift has broken again.")]),
  dict(level="B1+", title="Εδώ και: for (time up to now)",
       el="«Εδώ και» + χρονικό διάστημα, με ενεστώτα, για κάτι που συνεχίζεται.",
       en="**εδώ και** + a period with the **present tense** expresses *for* (up to now): *δεν έχει πληρώσει εδώ και μήνες* or *χρωστάει εδώ και έξι μήνες* (he has owed for six months). English uses the perfect; Greek often uses the plain present: *μένω εδώ εδώ και δύο χρόνια* (I have lived here for two years). **Εδώ και πόσο καιρό…;** = for how long…?",
       examples=[("Μένουμε εδώ και πέντε χρόνια.", "We've lived here for five years."), ("Εδώ και πόσο καιρό χρωστάει;", "How long has he owed money?"), ("Το ασανσέρ δεν δουλεύει εδώ και μια βδομάδα.", "The lift hasn't worked for a week.")]),
  dict(level="B2", title="Μας κόψουν το ασανσέρ: the ethical dative",
       el="Ο αδύνατος τύπος (μας, μου, σου) δείχνει ποιος επηρεάζεται.",
       en="A weak pronoun in the genitive can mark the person affected, often with feeling: *θα μας κόψουν το ασανσέρ* (they'll cut off our lift on us), *μου χάλασε το πλυντήριο* (my washing machine broke on me), *μη μου κλαίγεσαι* (don't come crying to me). English adds *on me / on us* or nothing at all.",
       examples=[("Μου χάλασε πάλι το θερμοσίφωνο.", "The water heater has broken on me again."), ("Μας έκοψαν το νερό.", "They cut off our water."), ("Μη μου αργείς!", "Don't be late on me!")]),
 ],
